create table public.catalysts(id uuid primary key default gen_random_uuid(),catalyst_key text not null unique,asset_id uuid not null references public.assets(id),opportunity_id uuid references public.opportunities(id),candidate_id uuid references public.jackpot_candidates(id),catalyst_type text not null,materiality text not null check(materiality in('LOW','MEDIUM','HIGH','VERY_HIGH','UNKNOWN')),source_classification text not null,source_confidence numeric,novelty text not null check(novelty in('LOW','MEDIUM','HIGH','UNKNOWN')),watch_window text not null check(watch_window in('ULTRA_SHORT','SHORT','MEDIUM')),watch_until timestamptz not null,current_state text not null,current_revision integer not null default 0,policy_version text not null,created_at timestamptz not null default now());
create table public.catalyst_revisions(id uuid primary key default gen_random_uuid(),catalyst_id uuid not null references public.catalysts(id),revision_number integer not null,state text not null,occurred_at timestamptz not null,observed_at timestamptz not null,available_at timestamptz not null,source_reference text not null,source_classification text not null,materiality text not null,activation_evidence jsonb not null default'[]',evidence_refs jsonb not null default'[]',details jsonb not null default'{}',revision_hash text not null,created_at timestamptz not null default now(),check(occurred_at<=observed_at and observed_at<=available_at),unique(catalyst_id,revision_number),unique(catalyst_id,revision_hash));
create table public.forecasts(id uuid primary key default gen_random_uuid(),forecast_key text not null unique,asset_id uuid not null references public.assets(id),opportunity_id uuid references public.opportunities(id),candidate_id uuid references public.jackpot_candidates(id),catalyst_id uuid references public.catalysts(id),forecast_version text not null,forecast_method text not null,model_version text not null,feature_set_version text not null,training_cutoff_at timestamptz,created_at timestamptz not null default now(),information_cutoff_at timestamptz not null,available_at timestamptz not null,horizon text not null check(horizon in('5m','30m','2h','24h')),expected_return numeric,lower_bound numeric,upper_bound numeric,probability_positive numeric,probability_2x numeric,probability_5x numeric,probability_10x numeric,confidence numeric,data_quality numeric,status text not null check(status in('AVAILABLE','INSUFFICIENT_DATA')),reason text,evidence_refs jsonb not null default'[]',agent_inputs jsonb not null default'{}',market_regime jsonb,check(information_cutoff_at<=available_at));
create table public.forecast_outcomes(id uuid primary key default gen_random_uuid(),forecast_id uuid not null unique references public.forecasts(id),outcome_policy_version text not null,target_at timestamptz not null,price_observed_at timestamptz,available_at timestamptz not null,status text not null check(status in('AVAILABLE','INSUFFICIENT_DATA')),reason text,actual_return numeric,direction_correct boolean,absolute_error numeric,range_hit boolean,max_favorable_excursion numeric,max_adverse_excursion numeric,calibration_bucket text,predicted_probability numeric,actual_outcome boolean,evidence_refs jsonb not null default'[]',created_at timestamptz not null default now());
create or replace function public.prevent_forecast_history_mutation()returns trigger language plpgsql as $$begin raise exception'Forecast and catalyst history is immutable';end$$;create trigger catalyst_revisions_immutable before update or delete on public.catalyst_revisions for each row execute function public.prevent_forecast_history_mutation();create trigger forecasts_immutable before update or delete on public.forecasts for each row execute function public.prevent_forecast_history_mutation();create trigger forecast_outcomes_immutable before update or delete on public.forecast_outcomes for each row execute function public.prevent_forecast_history_mutation();
alter table public.catalysts enable row level security;alter table public.catalyst_revisions enable row level security;alter table public.forecasts enable row level security;alter table public.forecast_outcomes enable row level security;create policy "public read catalysts" on public.catalysts for select using(true);create policy "public read catalyst revisions" on public.catalyst_revisions for select using(true);create policy "public read forecasts" on public.forecasts for select using(true);create policy "public read forecast outcomes" on public.forecast_outcomes for select using(true);grant select on public.catalysts,public.catalyst_revisions,public.forecasts,public.forecast_outcomes to anon,authenticated;grant all on public.catalysts,public.catalyst_revisions,public.forecasts,public.forecast_outcomes to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst'));
